sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float sweep;
uniform float radius;
uniform float feather;
half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float k = smoothstep(radius, radius + feather + 0.0001, length(d) / (0.5 * min(size.x, size.y)));
    float span = radians(sweep) * k;
    if (span <= 0.0) return image.eval(coord);
    half4 sum = half4(0.0);
    for (int i = 0; i < 48; i++) {
        float a = span * (float(i) / 47.0 - 0.5);
        sum += image.eval(c + float2(cos(a) * d.x - sin(a) * d.y, sin(a) * d.x + cos(a) * d.y));
    }
    return sum / 48.0;
}
